:root{--scene-lotus:url('data:image/png;base64,');--scene-crane:url('data:image/png;base64,');}

:root{
  --bg:#fbf8f1;--bg2:#f2ebdf;--paper:#fffdf8;--ink:#30261f;--muted:#625244;
  --tea:#744515;--tea2:#986120;--jade:#3c6759;--gold:#aa782c;--red:#a24e38;
  --line:rgba(92,67,42,.18);--line2:rgba(92,67,42,.10);
  --sans:"Microsoft YaHei","PingFang SC",sans-serif;
  --kai:"KaiTi","STKaiti","Kaiti SC","DFKai-SB","FangSong",serif;
}
*{box-sizing:border-box}
html,body{margin:0;width:100%;height:100%;overflow:hidden;background:var(--bg);color:var(--ink)}
body{font-family:var(--kai);background:
 radial-gradient(58vw 70vh at 83% 8%,rgba(191,214,201,.25),transparent 70%),
 radial-gradient(46vw 54vh at 8% 94%,rgba(230,204,163,.20),transparent 72%),
 linear-gradient(145deg,#fdfbf7 0%,#faf6ef 45%,#f4ede2 100%)}
button{font:inherit}
.shell{position:relative;width:100vw;height:100vh;min-width:1100px;min-height:680px;overflow:hidden;isolation:isolate}
.shell::before{content:"";position:absolute;inset:auto -1vw -7vh auto;width:46vw;height:37vh;background:url('data:image/png;base64,') right bottom/72% auto no-repeat;opacity:.07;z-index:-1}
.shell::after{content:"";position:absolute;right:5vw;top:5vh;width:10vw;height:10vw;background:url('data:image/png;base64,') center/contain no-repeat;opacity:.12;z-index:-1;animation:drift 13s ease-in-out infinite}
@keyframes drift{0%,100%{transform:translate(0,0) rotate(-.2deg)}50%{transform:translate(10px,-7px) rotate(.5deg)}}
@keyframes rise{from{opacity:0;transform:translateY(16px) scale(.992)}to{opacity:1;transform:none}}
@keyframes pulse{0%,100%{transform:scale(1);filter:saturate(.9)}50%{transform:scale(1.025);filter:saturate(1.08)}}
@keyframes line{0%,100%{transform:scaleX(.72);opacity:.35}50%{transform:scaleX(1);opacity:.68}}
@keyframes floaty{0%,100%{transform:translateY(0)}50%{transform:translateY(-4px)}}
@keyframes ripple{from{transform:scale(.6);opacity:.26}to{transform:scale(1.8);opacity:0}}

.app-switch{position:absolute;right:26px;top:20px;z-index:50;display:flex;gap:8px;font-family:var(--sans)}
.app-switch button{border:1px solid var(--line);background:rgba(255,255,255,.62);backdrop-filter:blur(14px);padding:8px 13px;border-radius:999px;color:var(--muted);cursor:pointer}
.app-switch button.active{color:var(--tea);border-color:rgba(170,120,44,.44);background:rgba(255,250,241,.82)}

.workspace{position:absolute;inset:0;display:block;animation:rise .45s ease both}
.workspace[hidden]{display:none}

/* ===== 左上身份岛 ===== */
.identity-island{position:absolute;left:2.8vw;top:4.5vh;width:30vw;min-width:360px;height:23vh;min-height:170px;padding:26px 110px 22px 30px;
  background:linear-gradient(130deg,rgba(255,253,247,.82),rgba(255,250,240,.28));
  border-left:3px solid rgba(170,120,44,.55);border-bottom:1px solid var(--line);
  clip-path:polygon(0 0,94% 0,100% 20%,89% 100%,0 100%);
  box-shadow:0 24px 70px rgba(86,62,36,.07);z-index:6}
.identity-island::after{content:"";position:absolute;right:14px;bottom:0;width:122px;height:118px;background:url('data:image/png;base64,') right bottom/contain no-repeat;opacity:.16}
.identity-island .hello{font-family:var(--sans);font-size:13px;color:var(--jade);letter-spacing:.14em;margin-bottom:9px;font-weight:700}
.identity-island h1{margin:0 0 8px;color:var(--tea);font-size:38px;line-height:1.18;font-weight:700;letter-spacing:.04em}
.identity-island p{margin:0;color:var(--muted);font-family:var(--sans);font-weight:600;font-size:14px}
.identity-island .mode{display:inline-flex;margin-top:17px;border-bottom:1px solid var(--line);gap:2px}
.identity-island .mode button{border:0;background:transparent;padding:8px 18px;color:var(--muted);cursor:pointer}
.identity-island .mode button.active{color:var(--tea);border-bottom:2px solid var(--gold);font-weight:700}

/* ===== 左中“陪伴提示” ===== */
.companion-note{position:absolute;left:3.4vw;top:31vh;width:28vw;min-width:350px;padding:18px 24px 18px 70px;border-top:1px solid var(--line);border-bottom:1px solid var(--line);z-index:5}
.companion-note::before{content:"♡";position:absolute;left:20px;top:15px;color:var(--red);font-family:var(--sans);font-size:30px}
.companion-note::after{content:"";position:absolute;right:0;bottom:-12px;width:90px;height:65px;background:url('data:image/png;base64,') right bottom/contain no-repeat;opacity:.10}
.companion-note strong{display:block;color:var(--tea);font-size:18px;margin-bottom:4px}
.companion-note span{font-family:var(--sans);font-size:13px;color:var(--muted);line-height:1.55}

/* ===== 左下时间轴，不是卡片 ===== */
.timeline{position:absolute;left:4vw;top:45vh;width:27vw;min-width:340px;height:35vh;padding:18px 20px 18px 24px;z-index:5}
.timeline::before{content:"";position:absolute;left:42px;top:56px;bottom:24px;width:1px;background:linear-gradient(var(--gold),rgba(170,120,44,.10))}
.timeline h2{margin:0 0 14px;color:var(--tea);font-size:23px;font-weight:700}
.timeline .item{display:grid;grid-template-columns:58px 24px 1fr;align-items:center;gap:10px;min-height:54px}
.timeline .time{font-family:var(--sans);font-size:12px;color:var(--jade);font-weight:700;text-align:right}
.timeline .dot{width:13px;height:13px;border:2px solid rgba(170,120,44,.55);border-radius:50%;background:var(--bg);position:relative;z-index:1}
.timeline .item:first-of-type .dot{background:var(--gold);box-shadow:0 0 0 6px rgba(170,120,44,.08)}
.timeline .txt{font-size:19px;color:var(--ink);font-weight:700}
.timeline .sub{font-family:var(--sans);font-size:12px;color:var(--muted);font-weight:600}

/* ===== 右侧主舞台：巨大、非矩形、叠层 ===== */
.main-stage{position:absolute;left:35vw;right:3vw;top:5vh;bottom:16vh;z-index:3}
.main-stage::before{content:"";position:absolute;inset:4% 0 5% 7%;background:
 linear-gradient(135deg,rgba(255,255,255,.58),rgba(255,249,238,.20));
 border:1px solid rgba(112,83,50,.10);border-radius:34px 80px 40px 120px;
 transform:skewX(-3deg);box-shadow:0 36px 80px rgba(91,66,39,.06);z-index:-1}
.main-stage::after{content:"";position:absolute;right:2%;bottom:1%;width:22vw;height:18vh;background:url('data:image/png;base64,') right bottom/contain no-repeat;opacity:.055;z-index:-1}
.stage-title{position:absolute;left:11%;top:7%;right:5%;display:flex;align-items:flex-start;justify-content:space-between}
.stage-title .label{font-family:var(--sans);font-size:12px;color:var(--jade);font-weight:700;letter-spacing:.18em}
.stage-title h2{font-size:28px;margin:5px 0 0;color:var(--tea);font-weight:700}
.stage-title .mini{font-family:var(--sans);font-size:12px;color:var(--muted);padding-top:8px}
.stage-title::after{content:"";position:absolute;left:0;right:20%;bottom:-12px;height:1px;background:linear-gradient(90deg,var(--gold),transparent);transform-origin:left;animation:line 6s ease-in-out infinite}

.center-message{position:absolute;left:12%;right:8%;top:28%;bottom:28%;display:flex;flex-direction:column;justify-content:center;align-items:center;text-align:center}
.center-message .seal{position:absolute;left:6%;top:8%;width:74px;height:74px;border-radius:50%;border:1px solid rgba(170,120,44,.20);display:grid;place-items:center;color:var(--gold);font-size:23px;animation:floaty 5s ease-in-out infinite}
.center-message h3{margin:0 0 12px;font-size:44px;color:var(--tea);font-weight:700;line-height:1.24;max-width:12em}
.center-message p{margin:0;max-width:39em;font-family:var(--sans);font-size:15px;line-height:1.8;color:var(--muted);font-weight:600}
.center-message::after{content:"";position:absolute;right:0;bottom:-5%;width:120px;height:95px;background:url('data:image/png;base64,') center/contain no-repeat;opacity:.10;animation:drift 10s ease-in-out infinite reverse}

.action-band{position:absolute;left:9%;right:2%;bottom:8%;height:96px;display:grid;grid-template-columns:1.45fr .75fr;gap:22px;align-items:center}
.primary-action{height:86px;position:relative;border:0;background:linear-gradient(90deg,rgba(170,120,44,.11),rgba(83,122,106,.09));clip-path:polygon(3% 0,100% 0,96% 100%,0 86%);cursor:pointer;color:var(--tea);font-size:23px;font-weight:700;text-align:left;padding-left:18%;overflow:hidden;transition:.22s ease}
.primary-action::before{content:"✦";position:absolute;left:12%;font-family:var(--sans);font-size:22px;color:var(--gold)}
.primary-action:hover{transform:translateY(-3px);filter:saturate(1.08)}
.primary-action:active{transform:translateY(0) scale(.985)}
.secondary-action{height:66px;border:0;border-bottom:1px solid var(--gold);background:transparent;color:var(--tea);font-size:18px;font-weight:700;cursor:pointer;position:relative}
.secondary-action::after{content:"";position:absolute;right:6px;bottom:0;width:90px;height:58px;background:url('') right bottom/contain no-repeat;opacity:.10}

/* ===== 底部 dock ===== */
.dock{position:absolute;left:3.5vw;right:3vw;bottom:2.5vh;height:10vh;min-height:74px;display:grid;grid-template-columns:repeat(4,1fr) 1.35fr;align-items:end;gap:10px;z-index:8}
.dock button{position:relative;height:68px;border:0;background:transparent;color:var(--muted);cursor:pointer;transition:.22s ease}
.dock button .icon{display:block;font-family:var(--sans);font-size:20px;color:var(--gold);margin-bottom:5px}
.dock button .text{font-size:16px;font-weight:700}
.dock button::after{content:"";position:absolute;left:20%;right:20%;bottom:0;height:1px;background:transparent}
.dock button.active{color:var(--tea);transform:translateY(-5px)}
.dock button.active::after{background:linear-gradient(90deg,transparent,var(--gold),transparent)}
.dock button:hover{transform:translateY(-4px);color:var(--tea)}
.contact{height:68px!important;border-left:1px solid var(--line)!important;font-family:var(--sans)!important;font-weight:700!important;color:var(--red)!important}

/* ===== 点击 ripple ===== */
.clickable{position:relative;overflow:hidden}
.clickable.pressed::after{content:"";position:absolute;left:45%;top:45%;width:28px;height:28px;border-radius:50%;background:rgba(170,120,44,.22);animation:ripple .42s ease-out both;pointer-events:none}

/* ===== 待办 / 我的：真正换构图，不只是换内容 ===== */
.todo-stage .center-message{align-items:flex-start;text-align:left;left:10%;right:43%;top:20%;bottom:22%}
.todo-stage .center-message h3{font-size:35px;max-width:9em}
.todo-stage .planner{position:absolute;right:6%;top:22%;width:38%;bottom:18%;border-left:1px solid var(--line);padding:18px 0 10px 26px}
.planner h4{margin:0 0 10px;color:var(--tea);font-size:22px}
.planner .date{padding:12px 0;border-bottom:1px solid var(--line2)}
.planner .date b{display:block;font-size:17px;color:var(--ink)}
.planner .date span{font-family:var(--sans);font-size:12px;color:var(--muted)}
.mine-stage .center-message{left:11%;right:45%;align-items:flex-start;text-align:left}
.mine-stage .history{position:absolute;right:6%;top:20%;width:39%;bottom:18%;overflow:hidden}
.history .row{padding:14px 0;border-bottom:1px solid var(--line2)}
.history b{display:block;color:var(--tea);font-size:18px}
.history span{font-family:var(--sans);font-size:12px;color:var(--muted)}

/* ===== CARE：中心人像式主判断 + 环绕 5 个摘要岛 ===== */
.care-stage{left:34vw;right:3vw;top:7vh;bottom:11vh}
.care-stage::before{border-radius:80px 34px 120px 46px;transform:skewX(2deg)}
.care-center{position:absolute;left:29%;top:22%;width:42%;height:46%;display:flex;align-items:center;justify-content:center;text-align:center}
.care-center::before{content:"";position:absolute;width:31vw;height:31vw;max-width:430px;max-height:430px;border-radius:50%;border:1px solid rgba(170,120,44,.13);background:radial-gradient(circle,rgba(255,255,255,.76),rgba(246,238,225,.24) 62%,transparent 70%)}
.care-center::after{content:"";position:absolute;width:160px;height:140px;right:-16%;bottom:-10%;background:url('data:image/png;base64,') center/contain no-repeat;opacity:.11;animation:drift 11s ease-in-out infinite}
.care-center .inside{position:relative;z-index:2;max-width:27em}
.care-center .inside small{font-family:var(--sans);color:var(--jade);font-weight:700}
.care-center h3{margin:10px 0;font-size:34px;color:var(--tea);line-height:1.35}
.care-center p{font-family:var(--sans);font-size:13px;color:var(--muted);line-height:1.7}
.orbit{position:absolute;width:220px;min-height:102px;padding:15px 68px 14px 16px;border-bottom:1px solid var(--line);transition:.22s ease;cursor:pointer}
.orbit:hover{transform:translateY(-4px)}
.orbit::after{content:"";position:absolute;right:5px;bottom:3px;width:64px;height:55px;background:url('data:image/png;base64,') center/contain no-repeat;opacity:.12}
.orbit b{display:block;color:var(--tea);font-size:20px;margin-bottom:5px}
.orbit span{font-family:var(--sans);font-size:12px;color:var(--muted);font-weight:600}
.o1{left:4%;top:18%} .o2{left:4%;bottom:18%} .o3{right:3%;top:15%} .o4{right:3%;top:43%} .o5{right:5%;bottom:13%}
.o2::after{background-image:url('data:image/png;base64,')} .o3::after{background-image:url('data:image/png;base64,')} .o4::after{background-image:url('data:image/png;base64,')} .o5::after{background-image:url('data:image/png;base64,')}
.care-tabs{position:absolute;left:35vw;right:4vw;top:4vh;height:38px;display:flex;gap:28px;align-items:center;z-index:7;border-bottom:1px solid var(--line)}
.care-tabs button{border:0;background:transparent;color:var(--muted);padding:6px 0;cursor:pointer}
.care-tabs button.active{color:var(--tea);border-bottom:1px solid var(--gold);font-weight:700}

@media(max-width:1150px){.shell{min-width:0;overflow:auto}body{overflow:auto}.identity-island{width:42vw}.main-stage{left:38vw}}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important}}

/* =====================================================================
   V5.4.1 · Motion Stage
   荷花开屏 / 字体墨显 / 文字生树 / Pointer Drag Parallax / 水波反馈
   ===================================================================== */

:root {
  --drag-x: 0px;
  --drag-y: 0px;
  --drag-x-soft: 0px;
  --drag-y-soft: 0px;
}

/* ---------- lotus opening ---------- */
.lotus-opening {
  position:fixed;
  inset:0;
  z-index:999;
  display:grid;
  place-items:center;
  overflow:hidden;
  background:
    radial-gradient(circle at 50% 58%, rgba(255,255,255,.93), rgba(249,244,235,.96) 44%, rgba(242,232,216,.98) 100%);
  cursor:pointer;
  transition:opacity .65s ease, visibility .65s ease;
}
.lotus-opening.is-done {
  opacity:0;
  visibility:hidden;
  pointer-events:none;
}
.lotus-opening::before {
  content:"";
  position:absolute;
  width:min(64vw,900px);
  height:min(25vw,330px);
  left:50%;
  top:58%;
  transform:translate(-50%,-50%) scale(.65);
  background:url('data:image/png;base64,') center/contain no-repeat;
  opacity:.02;
  animation:opening-water 2.25s cubic-bezier(.2,.8,.2,1) forwards;
}
.lotus-opening::after {
  content:"";
  position:absolute;
  width:180px;
  height:180px;
  left:50%;
  top:52%;
  transform:translate(-50%,-50%) scale(.18) rotate(-9deg);
  background:url('data:image/png;base64,') center/contain no-repeat;
  opacity:0;
  filter:saturate(.82) drop-shadow(0 20px 32px rgba(111,78,38,.08));
  animation:opening-lotus 1.8s .12s cubic-bezier(.16,.82,.18,1) forwards;
}
@keyframes opening-water {
  0% { opacity:0; transform:translate(-50%,-50%) scale(.55); }
  40% { opacity:.08; }
  100% { opacity:.16; transform:translate(-50%,-50%) scale(1.05); }
}
@keyframes opening-lotus {
  0% { opacity:0; transform:translate(-50%,-50%) scale(.18) rotate(-9deg); filter:blur(5px) saturate(.55); }
  42% { opacity:.92; }
  76% { transform:translate(-50%,-50%) scale(1.10) rotate(.8deg); }
  100% { opacity:.98; transform:translate(-50%,-50%) scale(1) rotate(0); filter:blur(0) saturate(.9); }
}
.opening-copy {
  position:absolute;
  left:50%;
  top:24%;
  transform:translateX(-50%);
  text-align:center;
  color:var(--tea);
}
.opening-copy .brand {
  display:flex;
  justify-content:center;
  gap:.14em;
  font-family:var(--kai);
  font-size:clamp(48px,5vw,82px);
  font-weight:700;
  letter-spacing:.16em;
}
.opening-copy .brand span {
  opacity:0;
  filter:blur(8px);
  transform:translateY(12px);
  animation:opening-char .82s cubic-bezier(.2,.8,.2,1) forwards;
}
.opening-copy .brand span:nth-child(1) { animation-delay:.36s; }
.opening-copy .brand span:nth-child(2) { animation-delay:.58s; }
.opening-copy .sub {
  margin-top:12px;
  font-family:var(--sans);
  font-size:12px;
  font-weight:700;
  color:var(--muted);
  letter-spacing:.28em;
  opacity:0;
  animation:opening-sub .75s 1.06s ease forwards;
}
.opening-copy .skip {
  margin-top:20px;
  font-family:var(--sans);
  color:rgba(75,61,47,.55);
  font-size:11px;
  opacity:0;
  animation:opening-sub .6s 1.32s ease forwards;
}
@keyframes opening-char {
  to { opacity:1; filter:blur(0); transform:none; }
}
@keyframes opening-sub {
  to { opacity:1; }
}

/* ---------- ink text reveal ---------- */
.ink-reveal {
  display:inline-block;
}
.ink-reveal > .ink-char {
  display:inline-block;
  opacity:0;
  filter:blur(5px);
  transform:translateY(8px) scale(.985);
  animation:ink-char-in .56s cubic-bezier(.2,.82,.2,1) forwards;
}
@keyframes ink-char-in {
  64% { opacity:1; filter:blur(.4px); }
  100% { opacity:1; filter:blur(0); transform:none; }
}

/* ---------- title grows a tree ---------- */
.title-tree {
  display:inline-block;
  position:relative;
  width:82px;
  height:74px;
  margin-left:10px;
  vertical-align:middle;
  transform:translateY(8px);
  pointer-events:none;
}
.title-tree svg {
  width:100%;
  height:100%;
  overflow:visible;
}
.title-tree .branch {
  fill:none;
  stroke:#9a681f;
  stroke-width:1.55;
  stroke-linecap:round;
  stroke-linejoin:round;
  stroke-dasharray:180;
  stroke-dashoffset:180;
  opacity:.78;
  animation:tree-grow 1.35s .38s cubic-bezier(.2,.75,.2,1) forwards;
}
.title-tree .branch.secondary {
  stroke:#55776b;
  stroke-width:1.15;
  animation-delay:.76s;
}
.title-tree .leaf {
  fill:#55776b;
  opacity:0;
  transform-box:fill-box;
  transform-origin:center;
  transform:scale(.2);
  animation:leaf-pop .45s cubic-bezier(.22,.9,.3,1.3) forwards;
}
.title-tree .leaf.l2 { animation-delay:1.02s; }
.title-tree .leaf.l3 { animation-delay:1.18s; }
.title-tree .leaf.l4 { animation-delay:1.34s; }
.title-tree .leaf.l5 { animation-delay:1.48s; }
@keyframes tree-grow {
  to { stroke-dashoffset:0; }
}
@keyframes leaf-pop {
  to { opacity:.72; transform:scale(1); }
}

/* ---------- draggable spatial parallax ---------- */
.main-stage,
.care-stage {
  cursor:grab;
  touch-action:none;
}
.main-stage.is-dragging,
.care-stage.is-dragging {
  cursor:grabbing;
}
.main-stage::after,
.care-stage::after {
  transform:translate3d(calc(var(--drag-x-soft) * .95),calc(var(--drag-y-soft) * .95),0);
  transition:transform .32s cubic-bezier(.2,.8,.2,1);
}
.main-stage .stage-title,
.main-stage .center-message,
.main-stage .care-center {
  transform:translate3d(calc(var(--drag-x) * -.11),calc(var(--drag-y) * -.11),0);
  transition:transform .36s cubic-bezier(.2,.8,.2,1);
}
.main-stage .action-band {
  transform:translate3d(calc(var(--drag-x) * -.05),calc(var(--drag-y) * -.05),0);
  transition:transform .38s cubic-bezier(.2,.8,.2,1);
}
.main-stage .seal,
.main-stage .orbit {
  transform:translate3d(calc(var(--drag-x) * -.18),calc(var(--drag-y) * -.18),0);
  transition:transform .34s cubic-bezier(.2,.8,.2,1);
}
.main-stage.is-dragging::after,
.main-stage.is-dragging .stage-title,
.main-stage.is-dragging .center-message,
.main-stage.is-dragging .action-band,
.main-stage.is-dragging .seal,
.main-stage.is-dragging .orbit {
  transition:none;
}
.drag-hint {
  position:absolute;
  right:4%;
  top:16%;
  z-index:10;
  display:flex;
  align-items:center;
  gap:8px;
  font-family:var(--sans);
  font-size:11px;
  font-weight:700;
  color:rgba(89,71,54,.48);
  pointer-events:none;
  transition:opacity .3s ease;
}
.drag-hint::before {
  content:"↔";
  font-size:15px;
  color:var(--gold);
}
.main-stage.is-dragging .drag-hint {
  opacity:0;
}

/* ---------- click water ripple & lotus burst ---------- */
.stage-ripple,
.lotus-burst {
  position:fixed;
  z-index:998;
  left:0;
  top:0;
  pointer-events:none;
  transform:translate(-50%,-50%);
}
.stage-ripple {
  width:24px;
  height:24px;
  border:1px solid rgba(83,103,89,.30);
  border-radius:50%;
  box-shadow:0 0 0 1px rgba(170,120,44,.06) inset;
  animation:stage-ripple .62s cubic-bezier(.2,.7,.2,1) forwards;
}
.stage-ripple::after {
  content:"";
  position:absolute;
  inset:-12px;
  border-radius:50%;
  border:1px solid rgba(170,120,44,.14);
}
@keyframes stage-ripple {
  0% { opacity:.72; transform:translate(-50%,-50%) scale(.3); }
  100% { opacity:0; transform:translate(-50%,-50%) scale(5.8); }
}
.lotus-burst {
  width:74px;
  height:74px;
  background:url('data:image/png;base64,') center/contain no-repeat;
  filter:drop-shadow(0 10px 18px rgba(114,81,41,.08));
  animation:lotus-burst .58s cubic-bezier(.16,.8,.25,1) forwards;
}
@keyframes lotus-burst {
  0% { opacity:0; transform:translate(-50%,-50%) scale(.2) rotate(-10deg); }
  42% { opacity:.72; }
  100% { opacity:0; transform:translate(-50%,-50%) scale(1.28) rotate(4deg); }
}

/* ---------- extra subtle art layers ---------- */
.stage-art-cloud {
  position:absolute;
  left:6%;
  bottom:18%;
  width:88px;
  height:52px;
  background:url('data:image/png;base64,') center/contain no-repeat;
  opacity:.065;
  pointer-events:none;
  animation:art-cloud 11s ease-in-out infinite;
}
.stage-art-flower {
  position:absolute;
  right:3%;
  top:27%;
  width:88px;
  height:74px;
  background:url('data:image/png;base64,') center/contain no-repeat;
  opacity:.075;
  pointer-events:none;
  animation:art-flower 9s ease-in-out infinite;
}
@keyframes art-cloud {
  0%,100% { transform:translate3d(0,0,0); }
  50% { transform:translate3d(10px,-3px,0); }
}
@keyframes art-flower {
  0%,100% { transform:rotate(-.5deg) translateY(0); }
  50% { transform:rotate(.7deg) translateY(-4px); }
}

.motion-replay {
  position:fixed;
  left:22px;
  bottom:18px;
  z-index:70;
  border:0;
  border-bottom:1px solid rgba(154,104,31,.30);
  background:rgba(255,255,255,.22);
  backdrop-filter:blur(10px);
  color:rgba(72,54,38,.64);
  padding:7px 10px;
  font-family:var(--sans);
  font-size:11px;
  cursor:pointer;
}

@media(prefers-reduced-motion:reduce) {
  .lotus-opening { display:none !important; }
  .ink-reveal > .ink-char,
  .title-tree .branch,
  .title-tree .leaf {
    opacity:1 !important;
    filter:none !important;
    transform:none !important;
    animation:none !important;
    stroke-dashoffset:0 !important;
  }
  .drag-hint,
  .stage-art-cloud,
  .stage-art-flower {
    animation:none !important;
  }
}


/* =====================================================================
   V5.4.2 · Four page-specific scenes + large climbing-vine growth
   ===================================================================== */

.page-scene {
  position:fixed;
  inset:0;
  z-index:997;
  pointer-events:none;
  overflow:hidden;
  opacity:0;
}
.page-scene.playing { opacity:1; }

/* shared scene veil: only a hint, never a full opaque cover */
.page-scene::before {
  content:"";
  position:absolute;
  inset:0;
  background:radial-gradient(circle at var(--scene-x,50%) var(--scene-y,50%),
    rgba(255,253,247,.60), rgba(255,250,242,.12) 26%, transparent 58%);
  opacity:0;
}

/* TODAY — water + lotus */
.page-scene[data-scene="today"].playing::before {
  animation:scene-soft-flash .72s ease-out both;
}
.scene-today-lotus,
.scene-care-crane,
.scene-mine-tree,
.scene-todo-leaves {
  position:absolute;
  left:var(--scene-x,50%);
  top:var(--scene-y,50%);
  transform:translate(-50%,-50%);
}
.scene-today-lotus {
  width:118px;
  height:118px;
  background:var(--scene-lotus) center/contain no-repeat;
  opacity:0;
}
.page-scene[data-scene="today"].playing .scene-today-lotus {
  animation:scene-lotus-open .76s cubic-bezier(.16,.82,.18,1) both;
}
.scene-today-ripple,
.scene-care-ring {
  position:absolute;
  left:var(--scene-x,50%);
  top:var(--scene-y,50%);
  width:42px;height:42px;
  border:1px solid rgba(77,117,101,.28);
  border-radius:50%;
  opacity:0;
}
.page-scene[data-scene="today"].playing .scene-today-ripple.r1 {
  animation:scene-ring .78s ease-out both;
}
.page-scene[data-scene="today"].playing .scene-today-ripple.r2 {
  animation:scene-ring .78s .12s ease-out both;
}

/* TODO — golden leaves / task-path sweep */
.scene-todo-track {
  position:absolute;
  left:9vw;
  right:8vw;
  top:50%;
  height:1px;
  background:linear-gradient(90deg,transparent,rgba(170,120,44,.55),rgba(83,103,89,.26),transparent);
  transform:scaleX(.15);
  transform-origin:left center;
  opacity:0;
}
.page-scene[data-scene="todo"].playing .scene-todo-track {
  animation:todo-track .74s cubic-bezier(.2,.8,.2,1) both;
}
.scene-todo-leaves {
  left:15vw;
  top:48%;
  width:72vw;
  height:120px;
  transform:none;
}
.scene-todo-leaves i {
  position:absolute;
  width:19px;height:10px;
  border-radius:90% 10% 90% 10%;
  background:linear-gradient(135deg,#bc8b3b,#6f8b74);
  opacity:0;
  transform:rotate(var(--rot,0deg));
}
.scene-todo-leaves i:nth-child(1){left:2%;top:54%;--rot:18deg}
.scene-todo-leaves i:nth-child(2){left:22%;top:32%;--rot:-22deg}
.scene-todo-leaves i:nth-child(3){left:43%;top:62%;--rot:12deg}
.scene-todo-leaves i:nth-child(4){left:64%;top:28%;--rot:-12deg}
.scene-todo-leaves i:nth-child(5){left:83%;top:48%;--rot:26deg}
.page-scene[data-scene="todo"].playing .scene-todo-leaves i {
  animation:todo-leaf .68s cubic-bezier(.2,.8,.2,1) both;
}
.page-scene[data-scene="todo"].playing .scene-todo-leaves i:nth-child(2){animation-delay:.06s}
.page-scene[data-scene="todo"].playing .scene-todo-leaves i:nth-child(3){animation-delay:.12s}
.page-scene[data-scene="todo"].playing .scene-todo-leaves i:nth-child(4){animation-delay:.18s}
.page-scene[data-scene="todo"].playing .scene-todo-leaves i:nth-child(5){animation-delay:.24s}

/* CARE — crane crossing + jade ring */
.scene-care-crane {
  left:auto;
  right:-120px;
  top:31%;
  width:112px;height:112px;
  transform:none;
  background:var(--scene-crane) center/contain no-repeat;
  opacity:0;
}
.page-scene[data-scene="care"].playing .scene-care-crane {
  animation:care-crane-cross .95s cubic-bezier(.18,.72,.2,1) both;
}
.scene-care-ring {
  left:66%;
  top:46%;
  width:120px;height:120px;
  border-color:rgba(83,103,89,.22);
}
.page-scene[data-scene="care"].playing .scene-care-ring {
  animation:care-ring .82s .12s ease-out both;
}

/* MINE — larger tree emergence */
.scene-mine-tree {
  left:61%;
  top:56%;
  width:340px;
  height:280px;
}
.scene-mine-tree svg { width:100%;height:100%;overflow:visible; }
.scene-mine-tree .trunk,
.scene-mine-tree .twig {
  fill:none;
  stroke-linecap:round;
  stroke-linejoin:round;
  stroke-dasharray:620;
  stroke-dashoffset:620;
}
.scene-mine-tree .trunk { stroke:#9b6b27;stroke-width:2.1;opacity:.68; }
.scene-mine-tree .twig { stroke:#517565;stroke-width:1.35;opacity:.56; }
.scene-mine-tree .leaf {
  fill:#517565;
  opacity:0;
  transform-box:fill-box;
  transform-origin:center;
  transform:scale(.15);
}
.page-scene[data-scene="mine"].playing .scene-mine-tree .trunk {
  animation:mine-tree-grow .95s cubic-bezier(.18,.75,.2,1) both;
}
.page-scene[data-scene="mine"].playing .scene-mine-tree .twig {
  animation:mine-tree-grow .85s .25s cubic-bezier(.18,.75,.2,1) both;
}
.page-scene[data-scene="mine"].playing .scene-mine-tree .leaf {
  animation:mine-leaf .38s .72s cubic-bezier(.2,.9,.25,1.25) both;
}
.page-scene[data-scene="mine"].playing .scene-mine-tree .leaf:nth-of-type(2){animation-delay:.79s}
.page-scene[data-scene="mine"].playing .scene-mine-tree .leaf:nth-of-type(3){animation-delay:.86s}
.page-scene[data-scene="mine"].playing .scene-mine-tree .leaf:nth-of-type(4){animation-delay:.93s}
.page-scene[data-scene="mine"].playing .scene-mine-tree .leaf:nth-of-type(5){animation-delay:1s}

/* Large climbing vine: grows along right/bottom edges, then fades to a calm background layer */
.vine-field {
  position:fixed;
  inset:0;
  z-index:2;
  pointer-events:none;
  overflow:hidden;
}
.vine-field svg {
  position:absolute;
  right:-2vw;
  bottom:-2vh;
  width:min(51vw,780px);
  height:min(86vh,820px);
  overflow:visible;
  filter:drop-shadow(0 10px 18px rgba(88,67,40,.035));
}
.vine-field .vine-main,
.vine-field .vine-side {
  fill:none;
  stroke-linecap:round;
  stroke-linejoin:round;
  stroke-dasharray:1500;
  stroke-dashoffset:1500;
}
.vine-field .vine-main { stroke:rgba(76,111,92,.37);stroke-width:2.1; }
.vine-field .vine-side { stroke:rgba(151,105,40,.28);stroke-width:1.35; }
.vine-field .vine-leaf {
  fill:rgba(76,111,92,.26);
  opacity:0;
  transform-box:fill-box;
  transform-origin:center;
  transform:scale(.18) rotate(-8deg);
}
.vine-field.grow .vine-main {
  animation:vine-grow-main 1.8s cubic-bezier(.18,.75,.2,1) both;
}
.vine-field.grow .vine-side {
  animation:vine-grow-main 1.45s .38s cubic-bezier(.18,.75,.2,1) both;
}
.vine-field.grow .vine-leaf {
  animation:vine-leaf-open .44s 1.1s cubic-bezier(.2,.9,.28,1.3) both;
}
.vine-field.grow .vine-leaf:nth-of-type(2){animation-delay:1.18s}
.vine-field.grow .vine-leaf:nth-of-type(3){animation-delay:1.26s}
.vine-field.grow .vine-leaf:nth-of-type(4){animation-delay:1.34s}
.vine-field.grow .vine-leaf:nth-of-type(5){animation-delay:1.42s}
.vine-field.grow .vine-leaf:nth-of-type(6){animation-delay:1.50s}
.vine-field.grow .vine-leaf:nth-of-type(7){animation-delay:1.58s}
.vine-field.grow .vine-leaf:nth-of-type(8){animation-delay:1.66s}
.vine-field.grow .vine-leaf:nth-of-type(9){animation-delay:1.74s}
.vine-field.grow .vine-leaf:nth-of-type(10){animation-delay:1.82s}

/* Make sure typography remains above vine */
.workspace,
.app-switch,
.motion-replay { z-index:5; }

@keyframes scene-soft-flash {
  0%{opacity:0} 36%{opacity:.85} 100%{opacity:0}
}
@keyframes scene-lotus-open {
  0%{opacity:0;transform:translate(-50%,-50%) scale(.18) rotate(-9deg);filter:blur(4px)}
