}
@keyframes mine-tree-grow { to{stroke-dashoffset:0} }
@keyframes mine-leaf { to{opacity:.55;transform:scale(1) rotate(0)} }
@keyframes vine-grow-main { to{stroke-dashoffset:0} }
@keyframes vine-leaf-open { to{opacity:1;transform:scale(1) rotate(0)} }

