/* =====================================================================
   V5.4.3 · Cinematic page openings
   每次主页面切换都播放一段“像首次开屏一样”的完整场景动画。
   ===================================================================== */

.page-scene {
  z-index: 1200 !important;
  background:
    radial-gradient(circle at 50% 48%, rgba(255,255,255,.96), rgba(250,245,236,.97) 46%, rgba(241,231,214,.985) 100%);
  opacity:0;
  visibility:hidden;
  transition:opacity .22s ease, visibility .22s ease;
}
.page-scene.playing {
  opacity:1;
  visibility:visible;
}
.page-scene::before {
  opacity:1 !important;
  background:
    radial-gradient(circle at 50% 52%, rgba(255,255,255,.70), transparent 36%),
    radial-gradient(circle at 20% 86%, rgba(216,229,219,.18), transparent 36%),
    radial-gradient(circle at 85% 13%, rgba(229,207,167,.15), transparent 34%) !important;
  animation:none !important;
}

