.page-scene[data-scene="mine"].playing .scene-mine-tree .leaf {
  animation:cin-mine-leaf .48s .82s cubic-bezier(.2,.9,.25,1.25) both !important;
}
.page-scene[data-scene="mine"]::after {
  content:"";
  position:absolute;
  right:6%;
  bottom:7%;
  width:26vw;
  height:24vh;
  background:var(--scene-vine-art) right bottom/contain no-repeat;
  opacity:0;
}
.page-scene[data-scene="mine"].playing::after {
  animation:cin-mine-art 1.2s .36s ease both;
}
@keyframes cin-mine-tree { to{stroke-dashoffset:0} }
@keyframes cin-mine-leaf { to{opacity:.62;transform:scale(1) rotate(0)} }
@keyframes cin-mine-art {
  0%{opacity:0;transform:translateY(18px) scale(.92)}
  100%{opacity:.11;transform:none}
}

/* More immersive vine while scene is playing */
.vine-field.scene-grow svg {
  width:min(62vw,900px) !important;
  height:min(96vh,940px) !important;
}
.vine-field.scene-grow .vine-main {
  stroke:rgba(74,108,89,.44) !important;
}
.vine-field.scene-grow .vine-leaf {
  fill:rgba(74,108,89,.31) !important;
}

/* During cinematic opening, slightly quiet the UI beneath */
body.scene-transition .workspace,
body.scene-transition .app-switch,
body.scene-transition .motion-replay {
  filter:blur(2px);
  opacity:.35;
  transition:filter .24s ease,opacity .24s ease;
}

@media(prefers-reduced-motion:reduce){
  .scene-copy{display:none!important}
  body.scene-transition .workspace,
  body.scene-transition .app-switch,
  body.scene-transition .motion-replay{filter:none!important;opacity:1!important}
}


/* =====================================================================
   V5.4.3.2 · Post-entry Ivy
   重要：爬山虎不属于切页过场。
   只有切页动画彻底结束并进入真实界面后，才开始慢慢攀爬、生枝、生叶。
   ===================================================================== */

/* Cinematic期间彻底隐藏爬山虎，避免它混入切片动画。 */
body.scene-transition .vine-field,
.page-scene.playing ~ .vine-field {
  opacity:0 !important;
}

/* 页面进入后，藤蔓环境层恢复。 */
.vine-field {
  opacity:1;
  transition:opacity .42s ease;
}

/* 每次进入页面先复位：一根藤、一片叶子都没有。 */
.vine-field:not(.post-entry-grow):not(.post-entry-settled) .vine-main,
.vine-field:not(.post-entry-grow):not(.post-entry-settled) .vine-side {
  stroke-dashoffset:1500 !important;
}
.vine-field:not(.post-entry-grow):not(.post-entry-settled) .vine-leaf {
  opacity:0 !important;
  transform:scale(.12) rotate(-10deg) !important;
}

/* 这次故意做得比切页动画慢很多，像真实植物生长。 */
.vine-field.post-entry-grow .vine-main {
  animation:post-vine-main-grow 3.35s .22s cubic-bezier(.28,.66,.24,1) both !important;
}
.vine-field.post-entry-grow .vine-side {
  animation:post-vine-branch-grow 2.45s 1.55s cubic-bezier(.28,.66,.24,1) both !important;
}

/* 叶片不是一起冒出来，而是沿着藤蔓方向逐片长。 */
.vine-field.post-entry-grow .vine-leaf {
  animation:post-vine-leaf-open .72s cubic-bezier(.18,.86,.25,1.24) both !important;
}
.vine-field.post-entry-grow .vine-leaf:nth-of-type(1){animation-delay:1.45s !important}
.vine-field.post-entry-grow .vine-leaf:nth-of-type(2){animation-delay:1.78s !important}
.vine-field.post-entry-grow .vine-leaf:nth-of-type(3){animation-delay:2.08s !important}
.vine-field.post-entry-grow .vine-leaf:nth-of-type(4){animation-delay:2.38s !important}
.vine-field.post-entry-grow .vine-leaf:nth-of-type(5){animation-delay:2.68s !important}
.vine-field.post-entry-grow .vine-leaf:nth-of-type(6){animation-delay:2.98s !important}
.vine-field.post-entry-grow .vine-leaf:nth-of-type(7){animation-delay:3.28s !important}
.vine-field.post-entry-grow .vine-leaf:nth-of-type(8){animation-delay:3.58s !important}
.vine-field.post-entry-grow .vine-leaf:nth-of-type(9){animation-delay:3.88s !important}
.vine-field.post-entry-grow .vine-leaf:nth-of-type(10){animation-delay:4.18s !important}

/* 生长完以后不是消失，而是安静地成为页面背景。 */
.vine-field.post-entry-settled .vine-main,
.vine-field.post-entry-settled .vine-side {
  stroke-dashoffset:0 !important;
  animation:none !important;
}
.vine-field.post-entry-settled .vine-leaf {
  opacity:1 !important;
  transform:scale(1) rotate(0) !important;
  animation:none !important;
}
.vine-field.post-entry-settled svg {
  opacity:.66;
  transition:opacity .8s ease;
}

/* 生长过程中稍微明显一些，最终再柔和下来。 */
.vine-field.post-entry-grow svg {
  opacity:.92;
}
.vine-field.post-entry-settled .vine-main {
  stroke:rgba(76,111,92,.31) !important;
}
.vine-field.post-entry-settled .vine-side {
  stroke:rgba(151,105,40,.22) !important;
}
.vine-field.post-entry-settled .vine-leaf {
  fill:rgba(76,111,92,.22) !important;
}

/* 页面内容始终压在植物上方。 */
.workspace,
.app-switch,
.motion-replay {
  z-index:5 !important;
}

@keyframes post-vine-main-grow {
  0% { stroke-dashoffset:1500; opacity:.16; }
  18% { opacity:.52; }
  100% { stroke-dashoffset:0; opacity:1; }
}
@keyframes post-vine-branch-grow {
  0% { stroke-dashoffset:1500; opacity:.10; }
  24% { opacity:.46; }
  100% { stroke-dashoffset:0; opacity:1; }
}
@keyframes post-vine-leaf-open {
  0% {
    opacity:0;
    transform:scale(.10) rotate(-14deg);
    filter:blur(1.5px);
  }
  64% {
    opacity:.82;
    transform:scale(1.08) rotate(2deg);
    filter:blur(0);
  }
  100% {
    opacity:1;
    transform:scale(1) rotate(0);
    filter:blur(0);
  }
}

@media(prefers-reduced-motion:reduce){
  .vine-field.post-entry-grow .vine-main,
  .vine-field.post-entry-grow .vine-side {
    stroke-dashoffset:0 !important;
    animation:none !important;
  }
  .vine-field.post-entry-grow .vine-leaf {
    opacity:.65 !important;
    transform:none !important;
    animation:none !important;
  }
}


/* =====================================================================
   V5.4.3.3 · Organic Bubble Flow
   椭圆气泡 + 自然曲线 + 页面进入后逐段生长 + 增删重连
   ===================================================================== */

.bubble-flow {
  position:absolute;
  left:3.2vw;
  top:44vh;
  width:29vw;
  min-width:365px;
  height:40vh;
  min-height:310px;
  z-index:7;
  padding:10px 8px 8px 14px;
  overflow:visible;
}
.flow-head {
  display:flex;
  align-items:flex-end;
  justify-content:space-between;
  padding:0 10px 5px 6px;
  position:relative;
  z-index:6;
}
.flow-kicker {
  font-family:var(--sans);
  color:var(--jade);
  font-size:10px;
  letter-spacing:.22em;
  font-weight:700;
  opacity:.66;
  margin-bottom:4px;
}
.flow-head h2 {
  margin:0;
  color:var(--tea);
  font-family:var(--kai);
  font-size:24px;
  font-weight:700;
  letter-spacing:.06em;
}
.flow-add {
  width:38px;
  height:38px;
  border:1px solid rgba(170,120,44,.24);
  border-radius:50%;
  background:rgba(255,253,248,.58);
  color:var(--tea);
  font-family:var(--sans);
  font-size:23px;
  line-height:1;
  cursor:pointer;
  box-shadow:0 10px 30px rgba(86,62,36,.045);
  transition:transform .24s cubic-bezier(.2,.8,.2,1),background .24s ease;
}
.flow-add:hover {
  transform:rotate(90deg) scale(1.06);
  background:rgba(255,250,239,.90);
}

.flow-canvas {
  position:relative;
  height:calc(100% - 48px);
  min-height:250px;
  overflow:visible;
}
.flow-links {
  position:absolute;
  inset:0;
  width:100%;
  height:100%;
  overflow:visible;
  z-index:1;
  pointer-events:none;
}
.flow-link {
  fill:none;
  stroke:url(#flowLineGradient);
  stroke-width:1.55;
  stroke-linecap:round;
  vector-effect:non-scaling-stroke;
  opacity:.72;
}
.flow-link.ghost {
  stroke:rgba(170,120,44,.16);
  stroke-width:4.5;
  opacity:.22;
  filter:blur(2px);
}
.flow-link.is-drawing {
  stroke-dasharray:1;
  stroke-dashoffset:1;
  animation:flow-line-grow .62s cubic-bezier(.25,.72,.22,1) forwards;
}
@keyframes flow-line-grow { to { stroke-dashoffset:0; } }

.flow-items {
  position:relative;
  z-index:2;
  height:100%;
  display:flex;
  flex-direction:column;
  justify-content:space-evenly;
  gap:8px;
  padding:5px 20px 2px 8px;
}
.flow-item {
  --shift:0px;
  position:relative;
  width:min(90%,300px);
  min-height:66px;
  margin-left:var(--shift);
  padding:12px 52px 11px 68px;
  border:1px solid rgba(111,82,48,.14);
  border-radius:52% 48% 46% 54% / 58% 45% 55% 42%;
  background:
    radial-gradient(circle at 20% 20%,rgba(255,255,255,.70),transparent 34%),
    linear-gradient(135deg,rgba(255,252,245,.83),rgba(243,232,213,.48));
  box-shadow:
    0 13px 30px rgba(82,61,39,.055),
    inset 0 0 28px rgba(255,255,255,.23);
  opacity:0;
  transform:scale(.62) translateY(8px);
  transform-origin:30% 50%;
  transition:
    opacity .42s ease,
    transform .52s cubic-bezier(.18,.88,.2,1.16),
    filter .35s ease,
    background .35s ease,
    border-color .35s ease;
}
.flow-item:nth-child(3n+2) {
  --shift:28px;
  border-radius:46% 54% 54% 46% / 48% 56% 44% 52%;
}
.flow-item:nth-child(3n) {
  --shift:8px;
  border-radius:55% 45% 49% 51% / 43% 58% 42% 57%;
}
.flow-item.revealed {
  opacity:1;
  transform:scale(1) translateY(0);
}
.flow-item.completed {
  opacity:.58;
  filter:saturate(.62);
  background:
    linear-gradient(135deg,rgba(255,253,249,.62),rgba(247,240,228,.31));
  border-color:rgba(111,82,48,.09);
  box-shadow:none;
}
.flow-item.completed.revealed:hover {
  opacity:.78;
  filter:saturate(.85);
}
.flow-item.pending {
  border-color:rgba(170,120,44,.30);
  background:
    radial-gradient(circle at 22% 15%,rgba(255,255,255,.86),transparent 31%),
    linear-gradient(135deg,rgba(255,250,239,.96),rgba(224,235,226,.62));
  box-shadow:
    0 14px 34px rgba(92,66,38,.07),
    0 0 0 1px rgba(170,120,44,.035) inset;
}
.flow-time {
  position:absolute;
  left:15px;
  top:50%;
  transform:translateY(-50%);
  font-family:var(--sans);
  color:var(--jade);
  font-size:13px;
  font-weight:800;
  letter-spacing:.02em;
}
.flow-item.completed .flow-time { color:#817463; }
.flow-title {
  display:block;
  color:var(--ink);
  font-family:var(--kai);
  font-size:18px;
  font-weight:700;
  line-height:1.2;
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
}
.flow-status {
  display:block;
  margin-top:3px;
  color:var(--muted);
  font-family:var(--sans);
  font-size:10.5px;
  font-weight:700;
  white-space:nowrap;
  overflow:hidden;
  text-overflow:ellipsis;
}
.flow-item.pending .flow-status { color:var(--tea2); }

/* 未完成：麦克风呼吸 */
.breath-mic {
  position:absolute;
  right:18px;
  top:50%;
  width:24px;
  height:28px;
  transform:translateY(-50%);
  display:none;
  place-items:center;
}
.pending .breath-mic { display:grid; }
.breath-mic::before,
.breath-mic::after {
  content:"";
  position:absolute;
  left:50%;
  top:50%;
  width:24px;
  height:24px;
  border:1px solid rgba(170,120,44,.26);
  border-radius:50%;
  transform:translate(-50%,-50%) scale(.65);
  opacity:0;
  animation:mic-breath-ring 2.35s ease-out infinite;
}
.breath-mic::after { animation-delay:1.12s; }
.mic-core {
  position:relative;
  width:9px;
  height:15px;
  border:1.7px solid var(--tea2);
  border-radius:7px;
  background:rgba(255,252,246,.65);
}
.mic-core::before {
  content:"";
  position:absolute;
  left:50%;
  bottom:-5px;
  width:9px;
  height:6px;
  border:1.4px solid var(--tea2);
  border-top:0;
  border-radius:0 0 8px 8px;
  transform:translateX(-50%);
}
.mic-core::after {
  content:"";
  position:absolute;
  left:50%;
  bottom:-8px;
  width:6px;
  height:1.4px;
  background:var(--tea2);
  transform:translateX(-50%);
}
@keyframes mic-breath-ring {
  0% { opacity:0; transform:translate(-50%,-50%) scale(.55); }
  22% { opacity:.55; }
  100% { opacity:0; transform:translate(-50%,-50%) scale(1.65); }
}

/* 删除按钮默认藏起来，不破坏画面 */
.flow-delete {
  position:absolute;
  right:-7px;
  top:-7px;
  width:25px;
  height:25px;
  border:1px solid rgba(129,83,50,.18);
  border-radius:50%;
  background:rgba(255,253,248,.94);
  color:#8c5b42;
  font-family:var(--sans);
  font-size:14px;
  cursor:pointer;
  opacity:0;
  transform:scale(.72);
  transition:.22s ease;
}
.flow-item:hover .flow-delete,
.flow-item:focus-within .flow-delete {
  opacity:1;
  transform:scale(1);
}
.flow-item.removing {
  opacity:0 !important;
  transform:scale(.25) rotate(-3deg) !important;
  filter:blur(3px);
  transition:.36s cubic-bezier(.4,0,.6,1) !important;
}

/* 新增编辑器 */
.flow-editor {
  position:absolute;
  left:8px;
  right:10px;
  bottom:-58px;
  z-index:10;
  display:flex;
  align-items:flex-end;
  gap:7px;
  padding:10px 11px;
  border:1px solid rgba(104,78,48,.14);
  border-radius:24px 30px 20px 28px;
  background:rgba(255,252,246,.92);
  backdrop-filter:blur(14px);
  box-shadow:0 18px 45px rgba(74,54,34,.08);
  transform-origin:30% 0;
  animation:flow-editor-in .28s cubic-bezier(.2,.8,.2,1) both;
}
.flow-editor[hidden] { display:none; }
.flow-editor label {
  display:flex;
  flex-direction:column;
  gap:4px;
  margin:0;
  min-width:80px;
}
.flow-editor label.grow { flex:1; }
.flow-editor label span {
  font-family:var(--sans);
  font-size:9px;
  font-weight:700;
  color:var(--muted);
}
.flow-editor input {
  min-width:0;
  width:100%;
  height:30px;
  border:0;
  border-bottom:1px solid var(--line);
  background:transparent;
  padding:2px 4px;
  color:var(--ink);
  font-family:var(--sans);
  font-size:11px;
  outline:none;
}
.flow-editor button {
  height:30px;
  border:0;
  border-bottom:1px solid rgba(170,120,44,.42);
  background:transparent;
  color:var(--tea);
  font-family:var(--sans);
  font-size:10px;
  font-weight:700;
  cursor:pointer;
}
@keyframes flow-editor-in {
  from { opacity:0; transform:translateY(-7px) scale(.97); }
  to { opacity:1; transform:none; }
}

/* 空状态 */
.flow-empty {
  height:100%;
  display:grid;
  place-items:center;
  color:rgba(98,82,68,.62);
  font-family:var(--kai);
  font-size:16px;
  opacity:0;
  animation:flow-empty-in .5s ease forwards;
}
@keyframes flow-empty-in { to { opacity:1; } }

/* 页面进入后的“长出来”节奏 */
.bubble-flow.flow-entering .flow-head {
  animation:flow-head-in .48s ease both;
}
@keyframes flow-head-in {
  from { opacity:0; transform:translateY(6px); }
  to { opacity:1; transform:none; }
}


.bubble-flow.flow-dense .flow-items { gap:4px; }
.bubble-flow.flow-dense .flow-item {
  min-height:54px;
  padding-top:8px;
  padding-bottom:8px;
}
.bubble-flow.flow-dense .flow-title { font-size:16px; }
.bubble-flow.flow-dense .flow-status { font-size:9.5px; }
.bubble-flow.flow-very-dense .flow-item {
  min-height:46px;
  padding-top:6px;
  padding-bottom:6px;
}
.bubble-flow.flow-very-dense .flow-title { font-size:15px; }

@media(max-height:760px) {
  .bubble-flow { top:43vh; height:38vh; }
  .flow-item { min-height:58px; padding-top:9px; padding-bottom:9px; }
  .flow-title { font-size:16px; }
}
@media(prefers-reduced-motion:reduce) {
  .flow-item { opacity:1 !important; transform:none !important; transition:none !important; }
  .flow-link { stroke-dashoffset:0 !important; animation:none !important; }
  .breath-mic::before,.breath-mic::after { animation:none !important; opacity:.18 !important; }
}


