  --grow-magnolia:url('data:image/png;base64,');
  --grow-jade:url('data:image/png;base64,');
}

/* =====================================================================
   V5.4.3.4 · Growing Art Stage
   1. 身份区长枝  2. 题签切换  3. 三层景深  4. 陪伴区一笔心形
   5. 页面进入顺序 + 照护生命节律链
   ===================================================================== */

/* ---------- 1. identity: less card, more composition ---------- */
.identity-island {
  clip-path:none !important;
  background:transparent !important;
  box-shadow:none !important;
  border:0 !important;
  padding:34px 92px 24px 52px !important;
  width:31.5vw !important;
  min-width:390px !important;
  overflow:visible !important;
}
.identity-island::after{display:none !important}
.identity-island::before{
  content:"";
  position:absolute;
  left:20px;right:8px;bottom:0;
  height:1px;
  background:linear-gradient(90deg,rgba(170,120,44,.44),rgba(92,67,42,.10),transparent);
  opacity:.55;
}
.identity-grow-branch{
  position:absolute;
  left:-1px;
  bottom:0;
  width:74px;
  height:96%;
  overflow:visible;
  pointer-events:none;
}
.identity-grow-branch .ig-main,
.identity-grow-branch .ig-side{
  fill:none;
  stroke-linecap:round;
  stroke-linejoin:round;
  stroke-dasharray:430;
  stroke-dashoffset:430;
}
.identity-grow-branch .ig-main{stroke:rgba(164,113,40,.70);stroke-width:2.1}
.identity-grow-branch .ig-side{stroke:rgba(63,103,87,.52);stroke-width:1.3}
.identity-grow-branch .ig-leaf{
  fill:rgba(63,103,87,.58);
  opacity:0;
  transform-box:fill-box;
  transform-origin:center;
  transform:scale(.15);
}

.identity-island .hello{
  font-family:var(--kai) !important;
  font-size:18px !important;
  letter-spacing:.12em !important;
  color:var(--jade) !important;
  font-weight:700 !important;
}
.identity-island h1{
  font-size:46px !important;
  letter-spacing:.06em !important;
  color:#784718 !important;
  margin-top:10px !important;
  text-shadow:0 1px 0 rgba(255,255,255,.44);
}
.identity-island p{
  margin-top:12px !important;
  font-size:14px !important;
  color:#5e5145 !important;
  font-weight:700 !important;
}

/* ---------- 2. mode becomes calligraphic labels ---------- */
.identity-island .mode{
  position:relative;
  display:flex !important;
  gap:18px !important;
  margin-top:21px !important;
  border:0 !important;
}
.identity-island .mode button{
  position:relative;
  padding:7px 10px 9px !important;
  border:0 !important;
  background:transparent !important;
  color:#756657 !important;
  font-family:var(--kai) !important;
  font-size:17px !important;
  font-weight:700 !important;
  letter-spacing:.12em;
}
.identity-island .mode button::after{
  content:"";
  position:absolute;
  left:7px;right:7px;bottom:0;
  height:2px;
  background:linear-gradient(90deg,transparent,var(--gold),rgba(170,120,44,.32),transparent);
  transform:scaleX(0);
  transform-origin:left;
  opacity:0;
}
.identity-island .mode button.active{
  color:var(--tea) !important;
}
.identity-island .mode button.active::after{
  opacity:1;
  transform:scaleX(1);
  animation:ink-tag-spread .72s cubic-bezier(.2,.8,.2,1) both;
}
@keyframes ink-tag-spread{
  0%{transform:scaleX(.05);filter:blur(2px);opacity:.18}
  65%{opacity:.85}
  100%{transform:scaleX(1);filter:none;opacity:.72}
}

/* ---------- 3. depth art: far / middle / near ---------- */
.page-art-layers{
  position:absolute;
  inset:0;
  overflow:hidden;
  pointer-events:none;
  z-index:1;
}
.page-art-layers span{position:absolute;display:block;will-change:transform}
.art-far{
