.workspace.page-bloom .identity-grow-branch .ig-leaf.l1{animation:identity-leaf .42s 1.05s cubic-bezier(.2,.9,.25,1.2) both}
.workspace.page-bloom .identity-grow-branch .ig-leaf.l2{animation:identity-leaf .42s 1.20s cubic-bezier(.2,.9,.25,1.2) both}
