.workspace.page-bloom .identity-island h1{animation:headline-ink-in .88s .86s cubic-bezier(.2,.8,.2,1) both}
.workspace.page-bloom .identity-island p{animation:soft-ink-in .55s 1.30s ease both}
.workspace.page-bloom .identity-island .mode{animation:soft-ink-in .55s 1.55s ease both}

