.workspace.page-bloom .companion-vine .cv-main{animation:identity-branch-grow 1.08s 2.12s ease both}
.workspace.page-bloom .companion-vine .cv-side{animation:identity-branch-grow .72s 2.60s ease both}
.workspace.page-bloom .companion-vine .cv-leaf.a{animation:identity-leaf .40s 2.76s ease both}
.workspace.page-bloom .companion-vine .cv-leaf.b{animation:identity-leaf .40s 2.95s ease both}
