.workspace.page-bloom .companion-note span:not(.companion-art *){animation:soft-ink-in .65s 2.58s ease both}

@keyframes identity-branch-grow{to{stroke-dashoffset:0}}
@keyframes identity-leaf{to{opacity:.72;transform:scale(1)}}
@keyframes soft-ink-in{
  from{opacity:0;filter:blur(4px);transform:translateY(6px)}
