  100%{opacity:1;filter:none;transform:none}
}
@keyframes art-depth-in{
  from{opacity:0;transform:translateY(6px)}
  to{opacity:1;transform:none}
}
@keyframes heart-draw-in{to{stroke-dashoffset:0}}

/* ---------- care flow becomes "生命节律链" ---------- */
#careFlow .flow-kicker{color:#4d7465}
