  border-radius:50%;
  background:radial-gradient(circle,rgba(255,253,248,.94) 0%,rgba(255,252,246,.86) 72%,rgba(255,252,246,.38) 89%,transparent 100%);
  box-shadow:0 0 46px rgba(255,252,244,.72);
  pointer-events:none;
}
.five-vein-stage .care-verdict-core{
  z-index:7 !important;
}
.five-vein-stage .care-vein-svg{
  z-index:3 !important;
}
.five-vein-stage .care-vein.trunk{
  display:none !important;
}
.five-vein-stage .care-vein.branch{
  stroke-width:1.65 !important;
  opacity:.72 !important;
  filter:none !important;
}
.five-vein-stage .care-vein.vein-shadow{
  stroke-width:4.2 !important;
  opacity:.13 !important;
  filter:blur(2.8px) !important;
}
.five-vein-stage .vein-leaf-group{
  opacity:0;
  fill:rgba(68,108,90,.50) !important;
}

/* 中央只保留月晕和主判断，不允许任何枝脉视觉穿入 */
.five-vein-stage .moon-ring.ring-a{
  border-color:rgba(175,128,56,.13) !important;
}
.five-vein-stage .moon-ring.ring-b{
  border-color:rgba(72,111,94,.07) !important;
}

/* 节点稍微向外推，让枝线终点更明确 */
.five-vein-stage .node-today{left:-1% !important;top:7% !important}
.five-vein-stage .node-med{left:-2% !important;bottom:5% !important}
.five-vein-stage .node-body{right:-1% !important;top:7% !important}
.five-vein-stage .node-mood{right:-2% !important;top:40% !important}
.five-vein-stage .node-safety{right:0% !important;bottom:4% !important}

/* 枝脉在 hover 时只加深，不突然变粗到抢视觉 */
.five-vein-stage .vein-node:hover{
  transform:translateY(-2px) scale(1.018) !important;
}


/* =====================================================================
   V5.7 · 常驻逐帧飞鹤
   - 使用用户提供的 9 帧鹤素材
   - 点击哪里飞到哪里
   - 页面切换不重置
   - 飞行才扇翅，静止时保持滑翔帧
   ===================================================================== */
.crane-companion {
  position:fixed;
  left:0;
  top:0;
  width:176px;
  height:130px;
  z-index:1400;
  pointer-events:none;
  opacity:0;
  transform:translate3d(0,0,0);
  will-change:transform;
  filter:drop-shadow(0 11px 13px rgba(67,56,43,.10));
}
.crane-companion.is-ready {
  opacity:.95;
  transition:opacity .5s ease;
}
.crane-companion.is-flying {
  filter:
    drop-shadow(0 13px 15px rgba(67,56,43,.11))
    drop-shadow(0 0 8px rgba(91,120,109,.07));
}
.crane-tilt {
  width:100%;
  height:100%;
  transform-origin:54% 54%;
  will-change:transform;
}
.crane-facing {
  width:100%;
  height:100%;
  transform-origin:center;
  will-change:transform;
}
.crane-frame {
  display:block;
  width:100%;
  height:100%;
  object-fit:contain;
  user-select:none;
  -webkit-user-drag:none;
}
.crane-companion:not(.is-flying) .crane-tilt {
  animation:crane-idle-float 5.2s ease-in-out infinite;
}
@keyframes crane-idle-float {
  0%,100% { transform:translateY(0) rotate(0deg); }
  50% { transform:translateY(-2.5px) rotate(.25deg); }
}

/* 首次提示，第一次点击后自动消失 */
.crane-hint {
  position:absolute;
  left:52%;
  top:10%;
  transform:translate(-10%,-100%);
  min-width:132px;
  padding:7px 10px;
  border:1px solid rgba(126,93,52,.12);
  border-radius:22px 28px 20px 26px;
  background:rgba(255,253,247,.80);
  backdrop-filter:blur(9px);
  color:rgba(82,67,51,.68);
  font-family:var(--sans);
  font-size:9px;
  font-weight:700;
  letter-spacing:.05em;
  text-align:center;
  white-space:nowrap;
  opacity:0;
  transition:opacity .35s ease,transform .35s ease;
}
.crane-companion.is-ready:not(.has-flown) .crane-hint {
  opacity:.88;
  transform:translate(-10%,-112%);
  animation:crane-hint-breathe 3.8s ease-in-out infinite;
}
@keyframes crane-hint-breathe {
  0%,100% { box-shadow:0 8px 24px rgba(80,62,41,.035); }
  50% { box-shadow:0 10px 30px rgba(80,62,41,.075); }
}

/* 飞行时留下一点极淡的“气流”，不是路径线 */
.crane-wind {
  position:fixed;
  z-index:1398;
  width:54px;
  height:1px;
  border-radius:99px;
  pointer-events:none;
  opacity:0;
  background:linear-gradient(90deg,transparent,rgba(78,112,98,.24),transparent);
  transform-origin:center;
}
.crane-wind.play {
  animation:crane-wind-fade .62s ease-out both;
}
@keyframes crane-wind-fade {
  0% { opacity:0; transform:scaleX(.2); }
  28% { opacity:.58; }
  100% { opacity:0; transform:scaleX(1.5); }
}

@media(prefers-reduced-motion:reduce) {
  .crane-companion:not(.is-flying) .crane-tilt { animation:none !important; }
  .crane-hint { animation:none !important; }
}


/* V5.7.1 · 直线飞行 + 27帧平滑化 */
.crane-companion.is-flying .crane-frame{
  image-rendering:auto;
}
.crane-wind{
  opacity:.75;
}


/* V5.7.2 · Ultra frame animation */
.crane-frame{
  image-rendering:auto;
  transform:translateZ(0);
  backface-visibility:hidden;
}
.crane-companion.is-flying .crane-frame{
  will-change:contents;
}


/* V5.7.3 · Integer-cycle flight solver */
.crane-companion[data-cycles]{
  --flight-cycle-valid:1;
}


/* =====================================================================
   V5.7.4 · 照护概览去爬山虎
   仅在：照护中心 → 概览 隐藏大面积爬山虎。
   其他页面继续保留原有植物生长逻辑。
   ===================================================================== */
body.care-overview-clean #vineField {
  opacity:0 !important;
  visibility:hidden !important;
  pointer-events:none !important;
}
body.care-overview-clean #vineField *,
body.care-overview-clean #vineField *::before,
body.care-overview-clean #vineField *::after {
  animation:none !important;
}


/* =====================================================================
   V5.8R · 优活像素机器人「小优」
   原 desksprite / 鹿系小佑已彻底移除。
   新机器人逻辑直接内嵌在本 HTML：捧心 / 抛心 / 走路 / 侧跑 / 说话 / 开心。
   ===================================================================== */
.youhuo-robot-mascot{
  position:fixed;
  left:0;
  top:0;
  width:112px;
  height:180px;
  z-index:1505;
  pointer-events:none;
  opacity:0;
  transform:translate3d(0,0,0);
  transition:opacity .28s ease;
  will-change:transform;
}
.youhuo-robot-mascot.is-ready{opacity:1}
.youhuo-robot-canvas{
  position:absolute;
  left:0;
  bottom:0;
  width:112px;
  height:180px;
  image-rendering:pixelated;
  image-rendering:crisp-edges;
  filter:
    drop-shadow(0 7px 6px rgba(65,49,36,.14))
    drop-shadow(0 0 1px rgba(255,255,255,.72));
  pointer-events:auto;
  touch-action:none;
  cursor:grab;
  user-select:none;
  -webkit-user-select:none;
}
.youhuo-robot-mascot.is-dragging{
  z-index:9999;
}
.youhuo-robot-mascot.is-dragging .youhuo-robot-canvas{
  cursor:grabbing;
}
.youhuo-robot-bubble{
  position:absolute;
  bottom:145px;
  right:88px;
  width:min(322px,calc(100vw - 28px));
  padding:10px 14px 11px;
  border:1px solid rgba(164,113,40,.38);
  border-radius:20px 25px 18px 24px;
  color:#49382a;
  background:
    radial-gradient(circle at 14% 12%,rgba(255,255,255,.9),transparent 35%),
    rgba(255,251,242,.96);
  box-shadow:0 12px 34px rgba(74,54,35,.12),inset 0 0 20px rgba(255,255,255,.34);
  font-family:"Microsoft YaHei","PingFang SC",sans-serif;
  font-size:12px;
  line-height:1.62;
  font-weight:650;
  letter-spacing:.01em;
  white-space:normal;
  backdrop-filter:blur(12px);
  opacity:0;
  visibility:hidden;
  translate:0 6px;
  transition:opacity .22s ease,translate .22s ease,visibility .22s step-end;
}
.youhuo-robot-mascot.bubble-right .youhuo-robot-bubble{
  right:auto;
  left:88px;
}
.youhuo-robot-bubble::after{
  content:"";
  position:absolute;
  bottom:-7px;
  right:28px;
  width:12px;
  height:12px;
  border-right:1px solid rgba(164,113,40,.30);
  border-bottom:1px solid rgba(164,113,40,.30);
  background:#fffaf0;
  transform:rotate(45deg);
}
.youhuo-robot-mascot.bubble-right .youhuo-robot-bubble::after{
  right:auto;
  left:28px;
}
.youhuo-robot-bubble.show{
  opacity:1;
  visibility:visible;
  translate:0 0;
  transition:opacity .22s ease,translate .22s ease,visibility 0s;
}
@media(prefers-reduced-motion:reduce){
  .youhuo-robot-mascot{transition:none}
  .youhuo-robot-bubble{transition:none}
}
